import { readFile, writeFile, mkdir, rm } from "node:fs/promises";
import * as pf from "../packages/core/src/index.js";
import { exportPhaserBundle } from "../packages/exporters/src/bundle.js";
// Reuses character art generated by PixelForge operations, then authors gameplay through a batch.
const p = pf.fromDocument(
  JSON.parse(
    await readFile("examples/character/character.sprite.json", "utf8"),
  ),
);
const batch = {
  version: "1.0",
  operations: [
    {
      op: "addAnimation",
      name: "idle",
      frames: [
        { frameId: "frame-0", durationMs: 350 },
        { frameId: "frame-1", durationMs: 450 },
      ],
      loop: true,
    },
    {
      op: "addAnimation",
      name: "jump",
      frames: [{ frameId: "frame-2", durationMs: 200 }],
      loop: false,
    },
    { op: "copyFrame", source: "frame-1", id: "attack-windup" },
    { op: "copyFrame", source: "frame-2", id: "attack-active" },
    {
      op: "drawRect",
      frame: "attack-active",
      layer: "base",
      x: 20,
      y: 14,
      width: 10,
      height: 2,
      color: 4,
    },
    {
      op: "drawRect",
      frame: "attack-active",
      layer: "base",
      x: 19,
      y: 12,
      width: 2,
      height: 6,
      color: 9,
    },
    {
      op: "addAnimation",
      name: "attack",
      frames: [
        { frameId: "attack-windup", durationMs: 120 },
        { frameId: "attack-active", durationMs: 220 },
        { frameId: "frame-0", durationMs: 180 },
      ],
      loop: false,
    },
    { op: "setSpriteOrigin", origin: { x: 0.5, y: 1 } },
    {
      op: "setCollisionBody",
      body: { type: "rectangle", x: 11, y: 5, width: 11, height: 25 },
    },
    {
      op: "addGameBox",
      box: {
        id: "body-hurt",
        name: "body",
        kind: "hurtbox",
        scope: { type: "project" },
        rect: { x: 11, y: 5, width: 11, height: 25 },
        enabled: true,
      },
    },
    {
      op: "addGameBox",
      box: {
        id: "blade-active",
        name: "weapon",
        kind: "hitbox",
        scope: { type: "entry", animation: "attack", index: 1 },
        rect: { x: 20, y: 12, width: 12, height: 8 },
        enabled: true,
      },
    },
    {
      op: "setAnchor",
      anchor: {
        id: "hand",
        name: "weapon_hand",
        x: 20,
        y: 15,
        scope: { type: "project" },
      },
    },
    {
      op: "setAnimationEvent",
      event: {
        id: "attack-start",
        animation: "attack",
        index: 1,
        name: "attack_start",
      },
    },
    {
      op: "setAnimationEvent",
      event: {
        id: "attack-end",
        animation: "attack",
        index: 2,
        name: "attack_end",
      },
    },
  ],
};
const character = pf.applyOperations(p, batch);
character.name = "Playground knight";
await mkdir("examples/phaser-playground", { recursive: true });
await writeFile(
  "examples/phaser-playground/character.ops.json",
  JSON.stringify(batch, null, 2) + "\n",
);
await writeFile(
  "examples/phaser-playground/character.sprite.json",
  pf.serializeProject(character),
);
// Only remove the exact generated output directories, never an arbitrary CLI path.
for (const layout of ["atlas", "spritesheet"] as const) {
  const output = `examples/phaser-playground/public/assets/${layout}`;
  await rm(output, { recursive: true, force: true });
  await exportPhaserBundle(character, output, {
    layout,
    name: "knight",
    columns: 3,
    padding: 2,
    maxWidth: 128,
    maxHeight: 128,
  });
}
